<?php $title='Client Profile'; require __DIR__.'/../layouts/header.php'; ?>
<div class="pagehead"><div><h1><?=e($client['full_name'])?></h1><p><?=e($client['client_type'])?> · <?=e($client['client_no'])?></p></div><div class="actions"><a class="secondary" href="<?=route('client.edit',['id'=>$client['id']])?>">Edit</a><?php if(App\Core\Auth::can('Client','delete')): ?><a class="danger" href="<?=route('client.archive',['id'=>$client['id']])?>" data-confirm="Archive this client?">Archive</a><?php endif; ?></div></div>
<div class="panel"><h2>Client Operations</h2><p><a href="<?=route('businesses')?>?q=<?=rawurlencode($client['full_name'])?>">Businesses</a> · <a href="<?=route('bank-statements',['client_id'=>$client['id']])?>">Bank Statements</a> · <a href="<?=route('invoices')?>">Invoices</a> · <a href="<?=route('documents')?>">Documents</a></p></div><section class="grid two"><div class="panel"><h2>Profile</h2><dl><dt>Email</dt><dd><?=e($client['email'])?></dd><dt>Phone</dt><dd><?=e($client['phone'])?></dd><dt>Address</dt><dd><?=e(trim(($client['address']??'').' '.($client['city']??'').' '.($client['state']??'').' '.($client['zip']??''))) ?></dd><dt>Balance</dt><dd><?=money((float)$client['balance'])?></dd></dl></div>
<div class="panel"><h2>Businesses</h2><?php foreach($client['businesses'] as $b): ?><div class="tile"><strong><?=e($b['business_name'])?></strong><span class="muted"><?=e($b['entity_type'])?></span></div><?php endforeach; ?><?php if(!$client['businesses']): ?><p class="muted">No businesses linked.</p><?php endif; ?></div></section>
<section class="grid two"><div class="panel"><h2>Comments</h2><form method="post" action="<?=route('client.comments',['id'=>$client['id']])?>"><?=csrf_field()?><textarea name="comment_detail" rows="3" required placeholder="Add a comment..."></textarea><button class="secondary">Add comment</button></form><div class="timeline"><?php foreach($client['comments'] as $c): ?><div class="timeline-item"><strong><?=e($c['comment_detail'])?></strong><small><?=e($c['created_at'])?></small><form method="post" action="<?=route('comment.edit',['id'=>$c['id']])?>" style="margin-top:8px;display:grid;gap:6px"><?=csrf_field()?><textarea name="comment_detail" rows="2"><?=e($c['comment_detail'])?></textarea><button class="secondary">Save edit</button></form></div><?php endforeach; ?></div></div>
<div class="panel"><h2>Services</h2><?php foreach($client['services'] as $s): ?><div class="tile"><strong><?=e($s['service_name'])?></strong><span class="muted"><?=e($s['status'])?></span></div><?php endforeach; ?></div></section>
